1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
10	import { capacityCheck, diskCapacityCheck } from "./capacity";
11	import { invoiceCreateData } from "./invoices";
12	import { maybeRewardReferral } from "./actions-growth";
13	import { currentPromo, promoPriceCents } from "./promotions";
14	import { extraDiskPerGbCents } from "./disk-expand";
15	import {
16	  EXTRA_DISK_MAX_ADD_GB,
17	  EXTRA_DISK_MAX_TOTAL_GB,
18	  effectiveDiskGB,
19	  extraDiskCentsAt,
20	  extraDiskLabel,
21	  normalizeExtraDiskGB,
22	} from "./extra-disk";
23	import { getSettingBool } from "./settings";
24	import { couponOrderDiscountCents } from "./coupon-order";
25	
26	export class OrderError extends Error {}
27	
28	export const orderSchema = z.object({
29	  planId: z.string().min(1),
30	  osTemplateId: z.string().min(1),
31	  hostname: z
32	    .string()
33	    .min(3)
34	    .max(40)
35	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
36	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
37	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
38	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
39	  // Optional checkout promo code. Uppercased + trimmed; the discount + all
40	  // redemption guards live in orderQuote / placeOrder.
41	  couponCode: z.string().trim().max(32).optional(),
42	});
43	
44	export type OrderIntent = {
45	  planId: string;
46	  osTemplateId: string;
47	  hostname: string;
48	  nodeId?: string;
49	  addonMalware?: boolean;
50	  addonBackup?: boolean;
51	  addonDocker?: boolean;
52	  termMonths?: number;
53	  dedicatedIp?: boolean;
54	  sshPublicKey?: string;
55	  sshKeyName?: string;
56	  free?: boolean;
57	  /**
58	   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
59	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
60	   * post-deploy expansion job is needed. Permanent — never shrinks.
61	   */
62	  extraDiskGB?: number;
63	  /** Checkout promo code (e.g. a "one free month" coupon), uppercased. */
64	  couponCode?: string;
65	};
66	
67	/**
68	 * The price an order was SOLD at: the total, and the promo rate that produced it.
69	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
70	 *
71	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
72	 * path quoted a total, charged the CARD its share of that total at Stripe, and
73	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
74	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
75	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
76	 * so a rotation between "customer clicked Deploy" and "customer came back from
77	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
78	 * out of the wallet with no new consent. With no balance to take it from, the
79	 * payment was captured and no server was created.
80	 *
81	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
82	 * Stripe metadata for exactly this reason; the order path was the one that
83	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
84	 * the customer was shown is not recomputed later, it is carried.
85	 *
86	 * `promoPercent` and `promoName` travel WITH the total because they are not
87	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
88	 * at (every later proration prices against it), and the promo name is the ledger
89	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
90	 * today's 15% would hand every later proration the wrong basis and print a
91	 * discount on the invoice that does not match the money taken.
92	 */
93	export type OrderPrice = {
94	  /** Total to charge, in cents — the figure the customer consented to. */
95	  chargeCents: number;
96	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
97	  promoPercent: number;
98	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
99	  promoName: string;
100	};
101	
102	/** The sold price implied by a quote — the ONE place a quote becomes a price. */
103	export function orderPriceOf(quote: {
104	  chargeCents: number;
105	  promo: { discountPercent: number; name: string };
106	}): OrderPrice {
107	  return {
108	    chargeCents: quote.chargeCents,
109	    promoPercent: quote.promo.discountPercent,
110	    promoName: quote.promo.name,
111	  };
112	}
113	
114	/**
115	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
116	 * well-formed: a half-parsed price would be worse than no price at all, because
117	 * the caller's fallback (re-quote) is at least internally consistent.
118	 */
119	export function parseOrderPrice(raw: unknown): OrderPrice | null {
120	  let obj: unknown = raw;
121	  if (typeof raw === "string") {
122	    try {
123	      obj = JSON.parse(raw);
124	    } catch {
125	      return null;
126	    }
127	  }
128	  if (!obj || typeof obj !== "object") return null;
129	  const { chargeCents, promoPercent, promoName } = obj as Record<string, unknown>;
130	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
131	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
132	  if (promoPercent < 0 || promoPercent > 100) return null;
133	  return { chargeCents, promoPercent, promoName: typeof promoName === "string" ? promoName : "" };
134	}
135	
136	/** Extract a plain OrderIntent from a deploy form. */
137	export function intentFromFormData(formData: FormData): OrderIntent {
138	  return {
139	    planId: String(formData.get("planId") ?? ""),
140	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
141	    hostname: String(formData.get("hostname") ?? ""),
142	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
143	    addonMalware: formData.get("addon_malware") === "1",
144	    addonBackup: formData.get("addon_backup") === "1",
145	    addonDocker: formData.get("addon_docker") === "1",
146	    termMonths: Number(formData.get("termMonths") ?? 1),
147	    dedicatedIp: formData.get("dedicatedIp") === "1",
148	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
149	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
150	    free: formData.get("free") === "1",
151	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
152	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
153	    // bought so it drops out of JSON.stringify: the intent is round-tripped
154	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
155	    // createOrderCheckout), and every byte of headroom matters there.
156	    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
157	    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
158	  };
159	}
