161	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
162	async function scheduleNode(planRamMB: number) {
163	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
164	  if (nodes.length === 0) return null;
165	  const loads = await Promise.all(
166	    nodes.map(async (n) => {
167	      const agg = await db.server.findMany({
168	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
169	        select: { plan: { select: { ramMB: true } } },
170	      });
171	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
172	      return { node: n, free: n.capacityRamMB - used };
173	    }),
174	  );
175	  loads.sort((a, b) => b.free - a.free);
176	  return loads[0].node;
177	}
178	
179	/** Validate + price an order without placing it. Throws OrderError on any problem. */
180	export async function orderQuote(intent: OrderIntent) {
181	  const parsed = orderSchema.safeParse(intent);
182	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
183	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
184	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
185	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
186	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
187	    throw new OrderError(
188	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
189	    );
190	  }
191	  const term = vpsTerm(Number(intent.termMonths ?? 1));
192	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
193	
194	  // Extra root disk, priced per GB/month and multiplied over the term exactly
195	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
196	  // promo — the customer pays the same $/GB whichever term they pick, and renews
197	  // at the same rate). Growth is one-way: this is permanent for the server.
198	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
199	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
200	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
201	  const extraDiskCents = extraDiskMonthlyCents * term.months;
202	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
203	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
204	  }
205	
206	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
207	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
208	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
209	  // real renewal price and this discounted value is the real first-term price.
210	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
211	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
212	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
213	  const promo = currentPromo(new Date());
214	  const planFirstTermCents = promoPriceCents(regularPlanCents, promo);
215	
216	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
217	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
218	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
219	  // so the deploy preview can show it; the redemption itself (count + per-user +
220	  // per-IP guards) is claimed atomically in placeOrder.
221	  let couponId: string | null = null;
222	  let couponDiscountCents = 0;
223	  let couponLabel = "";
224	  let couponError = "";
225	  let couponMaxRedemptions: number | null = null;
226	  let couponFirstTimeOnly = false;
227	  const code = (intent.couponCode ?? "").trim().toUpperCase();
228	  if (code) {
229	    if (!(await getSettingBool("coupons_enabled", true))) {
230	      couponError = "Promo codes are currently disabled.";
231	    } else {
232	      const coupon = await db.coupon.findUnique({ where: { code } });
233	      if (!coupon) {
234	        couponError = "That code isn’t valid.";
235	      } else {
236	        const verdict = couponOrderDiscountCents(
237	          {
238	            kind: coupon.kind,
239	            value: coupon.value,
240	            serviceKind: coupon.serviceKind,
241	            planSlug: coupon.planSlug,
242	            maxTermMonths: coupon.maxTermMonths,
243	            active: coupon.active,
244	            expiresAt: coupon.expiresAt,
245	            maxRedemptions: coupon.maxRedemptions,
246	            timesRedeemed: coupon.timesRedeemed,
247	            minAmountCents: coupon.minAmountCents,
248	          },
249	          {
250	            serviceKind: "VPS",
251	            planSlug: plan.slug,
252	            planMonthlyCents: plan.priceCents,
253	            termMonths: term.months,
254	            planChargeCents: planFirstTermCents,
255	          },
256	          new Date(),
257	        );
258	        if (verdict.ok) {
259	          couponId = coupon.id;
260	          couponDiscountCents = verdict.discountCents;
261	          couponLabel = verdict.label;
262	          couponMaxRedemptions = coupon.maxRedemptions;
263	          couponFirstTimeOnly = coupon.firstTimeOnly;
264	        } else {
265	          couponError = verdict.error;
266	        }
267	      }
268	    }
269	  }
270	
271	  const chargeCents = planFirstTermCents - couponDiscountCents + ipCents + extraDiskCents;
272	  return {
273	    plan,
274	    os,
275	    term,
276	    chargeCents,
277	    promo,
278	    regularPlanCents,
279	    extraDiskGB,
280	    extraDiskMonthlyCents,
281	    extraDiskCents,
282	    couponId,
283	    couponDiscountCents,
284	    couponLabel,
285	    couponError,
286	    couponMaxRedemptions,
287	    couponFirstTimeOnly,
288	  };
289	}
290	
291	/**
292	 * Place an order: validate, charge the wallet (unless a free admin grant),
293	 * create the Server + PROVISION job. Returns the new server id. Does NOT
294	 * redirect. Callers must ensure funds exist (or pass free) — this still
295	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
296	 *
297	 * `sold` overrides the recomputed price with the one the order was actually SOLD
298	 * at — the card-paid path passes the figure stamped on the Checkout session
299	 * BEFORE the card was charged, so the confirm redirect settles the price the
300	 * customer consented to instead of re-pricing against whatever promo is running
301	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
302	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
303	 * quote, which it computed moments ago in the same request. See OrderPrice.
304	 */
305	/**
306	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
307	 * any failure so nothing partial survives. Kept separate from the order tx so a
308	 * wallet order can surface the failure before any money moves, and a card order
309	 * (already paid) can swallow it without stranding the paid provision.
310	 *
311	 * Guards, all enforced here: first-time-only (no prior paid server), the
312	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
313	 * (the two @@unique constraints on CouponRedemption).
314	 */
315	async function claimOrderCoupon(opts: {
316	  couponId: string;
317	  maxRedemptions: number | null;
318	  firstTimeOnly: boolean;
319	  userId: string;
320	  ipHash: string | null;
321	  amountCents: number;
322	}): Promise<void> {
323	  await db.$transaction(async (tx) => {
324	    if (opts.firstTimeOnly) {
325	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
326	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
327	    }
328	    // Atomic conditional increment — the only thing between the last free slot and
329	    // an over-redemption when two orders race for it.
330	    const claim = await tx.coupon.updateMany({
331	      where:
332	        opts.maxRedemptions === null
333	          ? { id: opts.couponId, active: true }
334	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
335	      data: { timesRedeemed: { increment: 1 } },
336	    });
337	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
338	    try {
339	      await tx.couponRedemption.create({
340	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
341	      });
342	    } catch {
343	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
344	      // this person. Throwing rolls back the increment above with it.
345	      throw new OrderError("You’ve already used this code.");
346	    }
347	  });
348	}
349	
350	/**
351	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
352	 *
353	 * The card leg discounts `cardCents` up front and only settles the redemption
354	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
355	 * paid provision is never stranded. Without this pre-check, a customer who has
356	 * already used a one-per-person code (or isn't first-time) still gets the
357	 * discounted card charge and the swallow hides it. So before we send them to
358	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
359	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
360	 * (a race could still lose the atomic claim at settle time — that path stays
361	 * swallowed by design), but it closes the everyday bypass.
362	 */
363	export async function orderCouponClaimable(opts: {
364	  couponId: string;
365	  firstTimeOnly: boolean;
366	  maxRedemptions: number | null;
367	  userId: string;
368	  ipHash: string | null;
369	}): Promise<{ ok: true } | { ok: false; error: string }> {
370	  if (opts.firstTimeOnly) {
371	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
372	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
373	  }
374	  const byUser = await db.couponRedemption.findUnique({
375	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
376	  });
377	  if (byUser) return { ok: false, error: "You’ve already used this code." };
378	  if (opts.ipHash) {
379	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
380	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
381	  }
382	  if (opts.maxRedemptions !== null) {
383	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
384	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
385	  }
386	  return { ok: true };
387	}
388	
389	export async function placeOrder(
390	  user: User,
391	  intent: OrderIntent,
392	  sold?: OrderPrice | null,
393	  opts?: { ipHash?: string | null },
394	): Promise<string> {
395	  const quote = await orderQuote(intent);
396	  const { plan, os, term, promo, extraDiskGB, extraDiskMonthlyCents, extraDiskCents } = quote;
397	  // Everything below bills off THESE three, never off `quote.chargeCents` /
398	  // `promo` directly: when a sold price is present it is the whole truth about
399	  // what this order costs and what rate it was sold at.
400	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
401	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
402	  const promoName = sold?.promoName || promo.name;
403	  // Note the intro discount on the billing document (first term only; renews full).
404	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
405	
406	  const cap = await capacityCheck(plan.id);
407	  if (!cap.ok) throw new OrderError(cap.reason);
408	
409	  let nodeId: string | null = null;
410	  if (intent.nodeId) {
411	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
412	    if (!n) throw new OrderError("Selected location is not available.");
413	    nodeId = n.id;
414	  } else {
415	    const n = await scheduleNode(plan.ramMB);
416	    nodeId = n?.id ?? null;
417	  }
418	
419	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
420	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
421	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
422	
423	  const addons = {
424	    malwareScanner: !!intent.addonMalware,
425	    dailyBackup: !!intent.addonBackup,
426	    docker: !!intent.addonDocker,
427	  };
428	  const isAdmin = user.role === "ADMIN";
429	  const freeRequested = !!intent.free && isAdmin;
430	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
431	
432	  // Claim the coupon BEFORE the order tx, so a wallet order fails cleanly (no
433	  // money moved) if the last slot just went. A free admin grant never consumes a
434	  // customer coupon. On the card-settle path the payment already cleared, so a
435	  // late claim failure must not strand the paid provision — log and continue.
436	  if (!freeRequested && quote.couponId && quote.couponDiscountCents > 0) {
437	    try {
438	      await claimOrderCoupon({
439	        couponId: quote.couponId,
440	        maxRedemptions: quote.couponMaxRedemptions,
441	        firstTimeOnly: quote.couponFirstTimeOnly,
442	        userId: user.id,
443	        ipHash: opts?.ipHash ?? null,
444	        amountCents: quote.couponDiscountCents,
445	      });
446	    } catch (e) {
447	      if (!sold) throw e; // wallet path: nothing charged yet — surface it
448	      console.error(`[order] coupon claim failed on a paid order for ${user.id}`, e);
449	    }
450	  }
451	
452	  const newKey = (intent.sshPublicKey ?? "").trim();
453	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
454	
455	  let server;
456	  try {
457	    server = await db.$transaction(async (tx) => {
458	      if (!freeRequested) {
459	        await debitWallet(tx, user.id, chargeCents);
460	        await tx.walletTransaction.create({
461	          data: {
462	            userId: user.id,
463	            amountCents: -chargeCents,
464	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`,
465	          },
466	        });
467	        // Billing document for the charge — created inside the same debit tx so it
468	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
469	        // Extra disk gets its OWN line so the customer can see exactly what the
470	        // permanent storage costs; the lines always sum back to chargeCents.
471	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`;
472	        const planLineCents = chargeCents - extraDiskCents;
473	        await tx.invoice.create({
474	          data: invoiceCreateData({
475	            userId: user.id,
476	            description: lineDesc,
477	            status: "PAID",
478	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
479	            lineItems: [
480	              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
481	              ...(extraDiskCents > 0
482	                ? [
483	                    {
484	                      description:
485	                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
486	                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
487	                      qty: 1,
488	                      unitCents: extraDiskCents,
489	                      amountCents: extraDiskCents,
490	                    },
491	                  ]
492	                : []),
493	            ],
494	          }),
495	        });
496	      }
497	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
498	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
499	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
500	      }
501	      const s = await tx.server.create({
502	        data: {
503	          name: intent.hostname,
504	          hostname: intent.hostname,
505	          userId: user.id,
506	          planId: plan.id,
507	          osTemplateId: os.id,
508	          nodeId,
509	          addons,
510	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
511	          // storage for easy restore") and re-confirms it on the Review step, but
512	          // `addons.dailyBackup` was write-only: the worker declares the key and
513	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
514	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
515	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
516	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
517	          // job was ever enqueued. A customer would discover the safety net they
518	          // were promised did not exist at the moment they needed it. Bridge it
519	          // here, at the point of sale.
520	          autoBackup: !!intent.addonBackup,
521	          backupIntervalHours: intent.addonBackup ? 24 : null,
522	          termMonths: term.months,
523	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
524	          // later proration prices the plan delta against this number instead of
525	          // whatever promo happens to be running when the customer clicks resize
526	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
527	          // half of a round trip by choosing the date, and pockets the spread.
528	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
529	          // this scalar and the cash collected describe the same transaction.
530	          // A free admin grant recorded as 100: nothing was paid for these months,
531	          // so nothing may ever prorate out of them.
532	          //
533	          // `promoPercent` — not `promo.discountPercent` — because a card-paid
534	          // order settles the rate it was SOLD at (see OrderPrice), which may no
535	          // longer be the promo running now. Recording today's rate against a
536	          // price collected under a different one is exactly the drift this
537	          // column exists to prevent.
538	          termPromoPercent: freeRequested ? 100 : promoPercent,
539	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
540	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
541	          // born at its full size, with no separate expansion job.
542	          extraDiskGB,
543	          wantsDedicatedIp: !!intent.dedicatedIp,
544	          isFree: freeRequested,
545	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
546	        },
547	      });
548	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
549	      return s;
550	    });
551	  } catch (e) {
552	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
553	    throw e;
554	  }
555	
556	  await db.auditLog.create({
557	    data: {
558	      userId: user.id,
559	      action: "server.order",
560	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
561	    },
562	  });
563	  if (!freeRequested) {
564	    try {
565	      await maybeRewardReferral(user.id);
566	    } catch {
567	      /* non-fatal */
568	    }
569	  }
570	  return server.id;
571	}
