49	/** A free jailed username on the node, derived from the email + random salt. */
50	async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
51	  for (let i = 0; i < 8; i++) {
52	    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
53	    if (!isValidUnixUsername(name)) continue;
54	    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
55	    if (!taken) return name;
56	  }
57	  throw new Error("Could not allocate a username — try again.");
