259	/** Create a scoped database for an account (within the plan's maxDatabases). */
260	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
261	  const user = await requireUser();
262	  await assertNotImpersonating();
263	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
264	  if (!a) return { error: "Account not found." };
265	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
266	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
267	  // A short, safe suffix keyed off the account username: <user>_<slug>.
268	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
269	  const name = `${a.username}_${slug}`.slice(0, 64);
270	  const dbUser = name.slice(0, 32);
271	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
272	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
273	  // Count + create in ONE serializable transaction, so concurrent creates can't
274	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
275	  try {
276	    await db.$transaction(async (tx) => {
277	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
278	      if (n >= a.maxDatabases) throw new Error("CAP");
279	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
280	    }, { isolationLevel: "Serializable" });
281	  } catch (e) {
282	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
283	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
284	    return { error: "A database with that name already exists, or the request raced — try again." };
285	  }
286	  revalidatePath("/dashboard/hosting");
287	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
288	  return { ok: true, password };
289	}
