467	// ---------- Subdomains + addon domains + cron (cPanel-class site mgmt) -------
468	// Every value that reaches the node shell is validated here (isValidUnixUsername
469	// / isValidHostingDomain / isValidSubdomainLabel / cron validators) AND re-checked
470	// in the worker. Caps are enforced inside a Serializable transaction so concurrent
471	// creates cannot both read a stale count and blow past the plan (same discipline
472	// as createHostingDatabase). The task is queued in the SAME tx as the row create.
473	
474	const SITE_STATES = ["PENDING", "ACTIVE"] as const;
475	const MAX_CRON_JOBS = 20;
