477	/** Owner (or admin) + ACTIVE account, returning the fields the site actions need. */
478	async function ownedSiteAccount(id: string) {
479	  const user = await requireUser();
480	  // Impersonating admins must not create/destroy customer resources — cron is
481	  // arbitrary command execution as the customer's unix user; subdomains/addons
482	  // mint live vhosts. Matches createHostingAccount/createHostingDatabase (audit MED-3).
483	  await assertNotImpersonating();
484	  const a = await db.hostingAccount.findUnique({
485	    where: { id },
486	    select: { id: true, userId: true, status: true, username: true, primaryDomain: true, maxSites: true },
487	  });
488	  if (!a) return { error: "Account not found." as const };
489	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
490	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
491	  return { user, a };
492	}
