494	/**
495	 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
496	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
497	 * subdomain, or an addon domain. Before this, each creator only checked its own
498	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
499	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
500	 * This single check, used by all three creators, is the app-level invariant (no DB
501	 * unique can span three tables + a deliberately re-usable primaryDomain).
502	 */
503	async function isHostnameClaimed(name: string): Promise<boolean> {
504	  const [prim, sub, addon] = await Promise.all([
505	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
506	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
507	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
508	  ]);
509	  return prim + sub + addon > 0;
510	}
