548	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
549	  const ctx = await ownedSiteAccount(accountId);
550	  if ("error" in ctx) return { error: ctx.error };
551	  const { a } = ctx;
552	  const clean = String(label ?? "").trim().toLowerCase();
553	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
554	  const fqdn = `${clean}.${a.primaryDomain}`;
555	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
556	  // Reject if another tenant already claimed this exact hostname as an addon domain
557	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
558	  // path (audit HIGH-1, reverse direction).
559	  if (await isHostnameClaimed(fqdn)) {
560	    return { error: "That hostname is already in use on Nxeon." };
561	  }
562	  const { docroot } = subdomainPaths(a.username, clean);
563	  try {
564	    await db.$transaction(async (tx) => {
565	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
566	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
567	      if (subs + addons >= a.maxSites) throw new Error("CAP");
568	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
569	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
570	    }, { isolationLevel: "Serializable" });
571	  } catch (e) {
572	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
573	    return { error: "That subdomain already exists, or the request raced — try again." };
574	  }
575	  revalidatePath(`/dashboard/hosting/${accountId}`);
576	  return { ok: true };
577	}
