590	export async function createAddonDomain(accountId: string, domain: string): Promise<HostingResult> {
591	  const ctx = await ownedSiteAccount(accountId);
592	  if ("error" in ctx) return { error: ctx.error };
593	  const { a } = ctx;
594	  const name = normalizeHostingDomain(domain);
595	  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
596	  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
597	  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
598	  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
599	  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
600	  if (await isHostnameClaimed(name)) {
601	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
602	  }
603	  const { docroot } = addonDomainPaths(a.username, name);
604	  try {
605	    await db.$transaction(async (tx) => {
606	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
607	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
608	      if (subs + addons >= a.maxSites) throw new Error("CAP");
609	      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
610	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
611	    }, { isolationLevel: "Serializable" });
612	  } catch (e) {
613	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
614	    return { error: "That domain is already added, or the request raced — try again." };
615	  }
616	  revalidatePath(`/dashboard/hosting/${accountId}`);
617	  return { ok: true };
618	}
