646	  } catch (e) {
647	    if (e instanceof Error && e.message === "CAP") return { error: `You can schedule up to ${MAX_CRON_JOBS} cron jobs.` };
648	    return { error: "Couldn’t add the cron job — try again." };
649	  }
650	  revalidatePath(`/dashboard/hosting/${accountId}`);
651	  return { ok: true };
