/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
function strongPassword(len = 22): string {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const bytes = randomBytes(len);
  let out = "";
  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
  return out;
}

async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
  if (!password) throw new Error("Hosting node has no root credential on record.");
  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => { clearTimeout(timer); resolve(); })
      .on("error", (e) => { clearTimeout(timer); reject(e); })
      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
